uebungen.loesung:
SELECT bezeichnung, preis
FROM produkt
WHERE kategorie = 'Elektronik' AND preis < 150;

SELECT bezeichnung
FROM produkt
WHERE bezeichnung LIKE 'Schreibtisch%';

SELECT ort, COUNT(*) AS anzahl
FROM kunde
GROUP BY ort;

SELECT b.bestell_id, b.bestelldatum, k.name
FROM bestellung b
INNER JOIN kunde k ON b.kunden_id = k.kunden_id;

SELECT bezeichnung, preis
FROM produkt
WHERE preis > (SELECT AVG(preis) FROM produkt);

SELECT name, ort
FROM kunde
WHERE ort IN ('Köln', 'Hamburg');

SELECT bezeichnung, preis
FROM produkt
WHERE preis BETWEEN 100 AND 200;

SELECT DISTINCT ort
FROM kunde
ORDER BY ort ASC;

UPDATE produkt
SET preis = 259.00
WHERE produkt_id = 10;

UPDATE produkt
SET preis = preis * 1.10
WHERE kategorie = 'Zubehör';

SELECT bestell_id, produkt_id, menge,
       SUM(menge) OVER (PARTITION BY bestell_id) AS menge_bestellung
FROM bestellposition;

