SELECT bezeichnung, kategorie, preis,
       RANK() OVER (PARTITION BY kategorie ORDER BY preis DESC) AS rang
FROM produkt;

SELECT bezeichnung, lagerbestand
FROM produkt
WHERE bezeichnung LIKE 'Lauf%' OR lagerbestand < 50;

SELECT status, COUNT(*) AS anzahl
FROM bestellung
GROUP BY status;

SELECT k.nachname, b.bestell_id, b.bestelldatum
FROM bestellung b
INNER JOIN kunde k ON b.kunden_id = k.kunden_id;

SELECT bezeichnung, preis
FROM produkt
