SELECT nr, name, plz
FROM kunde
WHERE LENGTH(plz) <> 5;

SELECT nr, name, umsatz
FROM kunde
WHERE umsatz <= 0;

SELECT nr, name, email
FROM kunde
WHERE email NOT LIKE '%@%.%';

SELECT bestell_id, bestelldatum, lieferdatum
FROM bestellung
WHERE lieferdatum < bestelldatum;

SELECT (SELECT SUM(umsatz) FROM kunde) AS umsatz_alle,
       SUM(d.umsatz) AS umsatz_ohne_exakte_dubletten
FROM (SELECT DISTINCT name, plz, umsatz FROM kunde) AS d;
